import{z as l,x as n,o as B,c as o,q as t,j as C,D as e,d as A,s as i,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"监管资本下的定价","description":"","frontmatter":{"title":"监管资本下的定价","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc-regcap-pricing.md","filePath":"quant/rc-regcap-pricing.md","lastUpdated":1791413859000}'),D={name:"quant/rc-regcap-pricing.md"};function p(d,E,m,R,F,c){const r=n("Mermaid");return B(),o("div",null,[E[2]||(E[2]=t('<h1 id="监管资本下的定价" tabindex="-1">监管资本下的定价 <a class="header-anchor" href="#监管资本下的定价" aria-label="Permalink to &quot;监管资本下的定价&quot;">​</a></h1><div class="epigraph"><p>监管资本是按公式计提的忧患：你在风险中性世界里算出的正价差，必须在资本约束下再算一遍——回报按占用付租，报价为此让路。</p><footer>—— 据 Basel Committee, *The standardised approach for measuring counterparty credit risk exposures*, 2014（SA-CCR）与银行内部资金定价实践整理</footer></div><p><a href="/quant/rc-xva-linkage">上一课</a>把 KVA 列为 XVA 家族里最依赖口径的一项：它把资本占用的成本折进价格。本课补齐它的供给侧：监管资本如何按公式产生，产生之后如何写回每笔业务的报价。EAD 与 SA-CCR 的机制已在 <a href="/quant/sa-ccr-ead">SA-CCR 的 EAD</a> 讲清，本课默认那套记号，只谈定价闭环。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一笔衍生品的监管资本等于 \\(8\\%\\times\\mathrm{RWA}\\)（RWA 即资本的 12.5 倍），RWA 由 EAD、期限与对手权重生成。资本不是免费的：股东要求回报率 \\(r_e\\)，充足率 \\(8\\%\\) 意味着每元 RWA 每年要付约 \\(r_e\\times 8\\%\\) 的「资本租金」。缺口是双重的。公式侧：SA-CCR 的乘数、期限因子与对冲识别，如何让同一笔风险在不同组合结构下资本不同。定价侧：边际资本怎么算、摊给谁——摊错的银行会出现「单笔都亏、总体却盈利」或反过来的错觉，前一种误杀好业务，后一种用总盘子掩盖坏业务。</p><p><span class="marginnote">数字实例：股东要求回报 \\(r_e=15\\%\\)、充足率 8%，则每元 RWA 的年租金是 \\(15\\%\\times8\\%=1.2\\%\\)。若某笔业务 EAD 只占名义的 2%，每元名义摊到的租金就是 \\(1.2\\%\\times2\\%=2.4\\) 个基点——这是它必须在价差里挣回来的资本成本，还只是起点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公式侧要点：\\(\\mathrm{EAD}=\\alpha\\,(\\mathrm{RC}+\\mathrm{PFE})\\)，\\(\\alpha=1.4\\)；PFE 加总带一个乘数，净额结算与抵押同时压低 RC 与加总项；保证金式交易的期限因子随保证金期走，未保证金交易随剩余期限走——同一笔五年互换，抵押与否资本差数倍，这是抵押条款的资本价值。CVA 风险资本是第二层：对 CVA 自身的利差风险再计提（基本法、标准法与内部模型三档），与交易账户的市场资本分开记账。定价侧的机制是增量资本分配：新业务对总资本的增量 \\(\\Delta\\mathrm{RWA}\\) 才是它的真实占用，按名义或按平均权重摊都是错账。要求的价差近似为</p> \\[s \\approx \\frac{r_e \\times 8\\% \\times \\Delta\\mathrm{RWA}}{\\mathrm{EAD}}, \\]<p>再叠加 XVA 与运营成本。资本减压是反向操作：压缩净额集、缩短期限、增加抵押、用指数对冲 CVA 资本；每项都有公式上可验证的减压量与真实风险变化之差——这个差就是监管套利的空间，也是监管修补的时间表。</p><p><span class="marginnote">术语翻译：RC（重置成本）回答「对手今天倒了我要亏多少」，PFE（潜在未来暴露）回答「将来行情更糟时可能亏多少」，两者相加再乘 1.4 的审慎系数就是 EAD（违约暴露）。监管按这个公式数计提，而不是按统计意义上的期望暴露。</span></p>',11)),(B(),C(s,null,{default:e(()=>[i(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRADE%5B%22%E6%96%B0%E4%BA%A4%E6%98%93%22%5D%20--%3E%20EAD%5B%22EAD%EF%BC%9ARC%20%2B%20PFE%EF%BC%8C%E4%B9%98%201.4%22%5D%0A%20%20EAD%20--%3E%20RWA%5B%22RWA%EF%BC%9A%E6%9D%83%E9%87%8D%20%C3%97%20%E6%9C%9F%E9%99%90%E5%9B%A0%E5%AD%90%22%5D%0A%20%20RWA%20--%3E%20MARG%7B%22%E7%9C%8B%E5%A2%9E%E9%87%8F%20%CE%94RWA%22%7D%0A%20%20MARG%20--%3E%20PRICE%5B%22%E6%8A%A5%E4%BB%B7%EF%BC%9A%E8%B5%84%E6%9C%AC%E7%A7%9F%E9%87%91%20%2B%20XVA%20%2B%20%E6%88%90%E6%9C%AC%22%5D%0A%20%20PRICE%20--%3E%20RELIEF%5B%22%E8%B5%84%E6%9C%AC%E5%87%8F%E5%8E%8B%EF%BC%9A%E6%8A%B5%E6%8A%BC%20%2F%20%E5%87%80%E9%A2%9D%20%2F%20%E7%BC%A9%E6%9C%9F%E9%99%90%22%5D%0A%20%20RELIEF%20--%3E%20CHECK%7B%22%E5%87%8F%E5%8E%8B%E6%98%AF%E5%90%A6%E9%99%8D%E4%BD%8E%E7%9C%9F%E5%AE%9E%E9%A3%8E%E9%99%A9%3F%22%7D%0A%20%20CHECK%20--%3E%7C%22%E6%98%AF%22%7C%20KEEP%5B%22%E4%BF%9D%E7%95%99%E7%BB%93%E6%9E%84%22%5D%0A%20%20CHECK%20--%3E%7C%22%E5%90%A6%22%7C%20FLAG%5B%22%E6%A0%87%E4%B8%BA%E5%A5%97%E5%88%A9%EF%BC%8C%E5%86%99%E9%80%80%E5%87%BA%E5%88%A4%E6%8D%AE%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[A("资本定价闭环的机制在反馈：报价影响库存，库存影响资本，资本影响报价。没有增量分配的银行会系统性堆积「资本便宜、账面赚钱」的业务，直到总资本约束爆掉。SA-CCR 取代旧的重置成本法，机制动因正是旧公式对对冲不敏感：两笔反向交易的净风险为零而旧法资本不为零，压缩交易因此成为行业性操作。期限因子把保证金期写进资本：追保频率越低资本越高，这是监管对流动性风险的定价。KVA 与监管资本的分野在上一课已立——定价用哪个，取决于约束是监管硬约束还是管理目标；监管约束下 SA-CCR 的公式值就是硬约束，公式与经济风险之差既是套利，也是未来修补的坐标（XVA 侧的衔接见"),a("a",{href:"/quant/xva-bridge"},"到 XVA 的桥"),A("）。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"常见误区：把总资本按名义或平均权重摊给每笔业务，再挑「摊后赚钱」的做。摊错的账会让「单笔都亏」的组合在报表上总体盈利（或反之）；正确的尺子是增量——只问一个问题：这笔业务进来，总 RWA 多了多少？")],-1)),(B(),C(s,null,{default:e(()=>[i(r,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20QUOTE%5B%22%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20BOOK%5B%22%E5%BA%93%E5%AD%98%E7%BB%93%E6%9E%84%22%5D%0A%20%20BOOK%20--%3E%20CAP%5B%22%E6%80%BB%E8%B5%84%E6%9C%AC%E5%8D%A0%E7%94%A8%22%5D%0A%20%20CAP%20--%3E%7C%22%E8%B5%84%E6%9C%AC%E7%A7%9F%E9%87%91%E5%86%99%E5%9B%9E%E4%BB%B7%E6%A0%BC%22%7C%20QUOTE%0A%20%20OLD%5B%22%E6%97%A7%E6%B3%95%EF%BC%9A%E5%8F%8D%E5%90%91%E5%AF%B9%E5%86%B2%E5%87%80%E9%A3%8E%E9%99%A9%E4%B8%BA%E9%9B%B6%22%5D%20--%3E%20NONZERO%5B%22%E8%B5%84%E6%9C%AC%E5%8D%B4%E4%B8%8D%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20NONZERO%20--%3E%20COMPRESS%5B%22%E5%8E%8B%E7%BC%A9%E4%BA%A4%E6%98%93%E6%88%90%E4%B8%BA%E8%A1%8C%E4%B8%9A%E6%93%8D%E4%BD%9C%22%5D%0A%20%20COMPRESS%20--%3E%20REFORM%5B%22%E7%9B%91%E7%AE%A1%E6%8D%A2%20SA-CCR%22%5D%0A%20%20LOW%5B%22%E8%BF%BD%E4%BF%9D%E9%A2%91%E7%8E%87%E4%BD%8E%22%5D%20--%3E%20MF%5B%22%E6%9C%9F%E9%99%90%E5%9B%A0%E5%AD%90%E9%AB%98%22%5D%0A%20%20MF%20--%3E%20HICAP%5B%22%E8%B5%84%E6%9C%AC%E9%AB%98%EF%BC%9A%E5%AF%B9%E6%B5%81%E5%8A%A8%E6%80%A7%E9%A3%8E%E9%99%A9%E7%9A%84%E5%AE%9A%E4%BB%B7%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">量级感：股东回报要求 15% 时，每元 RWA 的年资本租金约 1.2%。租金摊到名义上是多少，取决于 EAD 密度——抵押的五年利率互换 EAD 常只有名义的百分之零点几，摊下来不到一个基点；无抵押、长期限的信用衍生品 EAD 密度可达名义的百分之几十，摊下来是几十上百个基点。报价前先算 EAD 密度，再谈基点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只走对手信用与 CVA 资本这一条线，不覆盖市场风险 FRTB 与信用、操作风险的完整版图。会计减值（IFRS 9 的预期信用损失）与监管资本是两本账：前者按账面计提影响利润表，后者按公式占用影响资本回报，「拨备充足」与「资本充足」不能互相冒充。辖区差异（欧盟 CRR、美国的过渡安排）只承认存在，不展开。最后，公式优化有边界：监管修补的历史——从重置成本法到 SA-CCR、从 CVA 基本法到标准法——说明套利空间的半衰期以年计，把商业模式建在套利上，要预先写好退出判据。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>资本租金等于回报要求乘充足率，摊到名义上取决于 EAD 密度：先算密度，再谈基点。</li><li>定价用增量资本；按名义或平均权重摊都是错账。</li><li>SA-CCR 的期限与保证金因子给抵押与压缩交易创造了可验证的减压量。</li><li>公式与经济风险之差既是套利也是监管修补的时间表，商业模式要写退出判据。</li><li>出处：据 BCBS SA-CCR（2014、2019 修订）与银行内部资金定价实践整理；XVA 侧见上一课与本栏 xva-bridge 一课。</li></ul>',5))])}const _=l(D,[["render",p]]);export{u as __pageData,_ as default};
